// get_availability — Validate Format
const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const serviceOrStaff = String(body.service_or_staff ?? '').trim();
const preferredDate = String(body.preferred_date ?? '').trim();
const preferredTime = String(body.preferred_time ?? '').trim();

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!serviceOrStaff) errors.push('service_or_staff is required');

if (!preferredDate) {
  errors.push('preferred_date is required (YYYY-MM-DD)');
} else if (!DATE_RE.test(preferredDate)) {
  errors.push('preferred_date must be formatted YYYY-MM-DD');
}

if (preferredTime && !TIME_RE.test(preferredTime)) {
  errors.push('preferred_time must be 24-hour HH:MM (or omitted)');
}

const escaped = serviceOrStaff.replace(/[,()]/g, '');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    service_or_staff: serviceOrStaff,
    ilike_term: '*' + escaped + '*',
    preferred_date: preferredDate,
    preferred_time: preferredTime || null,
  },
}];

const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;
return [{ json: { business_found: !!row, business_id: row ? row.id : null, business_timezone: row ? row.timezone : null } }];

const items = $input.all();
const row = items[0] && items[0].json && items[0].json.business_id ? items[0].json : null;

return [{
  json: {
    availability_source: row ? row.availability_source : 'not_tracked',
    calendar_id: row ? row.calendar_id : null,
    opening_hours: row && row.opening_hours ? row.opening_hours : {},
  },
}];

// get_availability — Resolve Date
// Runs after the business (and its timezone) is resolved, so "is this
// date in the past" is evaluated in the business's own timezone. Also
// computes this day's boundaries for the staff_roster branch, which is a
// single-day lookup rather than a rolling multi-day search.
const input = $('Validate Format').first().json;
const business = $('Normalize Business').first().json;
const tz = business.business_timezone || 'UTC';

const now = DateTime.now().setZone(tz);
const preferred = DateTime.fromISO(input.preferred_date + 'T' + (input.preferred_time || '00:00'), { zone: tz });

const errors = [];
if (!preferred.isValid) {
  errors.push('preferred_date/preferred_time is not a real date and time');
} else if (preferred.startOf('day') < now.startOf('day')) {
  errors.push('preferred_date is in the past');
}

const searchFrom = preferred.isValid && preferred < now ? now : preferred;
const targetDay = preferred.isValid ? preferred.startOf('day') : null;

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_timezone: tz,
    search_from_iso: searchFrom && searchFrom.isValid ? searchFrom.toISO() : null,
    target_weekday: targetDay ? targetDay.weekday : null,
    day_start_iso: targetDay ? targetDay.toISO() : null,
    day_end_iso: targetDay ? targetDay.endOf('day').toISO() : null,
  },
}];

// get_availability — Normalize Service Match
// A caller's service_or_staff may name a staff member rather than a
// service (e.g. "is Priya free"), so no match here is not an error --
// it just means duration falls back to a conservative default rather
// than a real service duration.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    service_matched: !!row,
    duration_minutes: row ? row.duration_minutes : 30,
  },
}];

// get_availability — Resolve Staff Ids
// try/catch reads whichever upstream branch actually ran: a named-staff
// match if one was found, otherwise every active staff member for this
// business (the template doesn't do strict service-to-staff filtering --
// see supabase/migrations/0002_multi_business.sql's note on `staff.services`).
let rows = [];
try {
  const primary = $('Normalize Staff By Name').first().json;
  if (primary && primary.staff_rows && primary.staff_rows.length) rows = primary.staff_rows;
} catch (e) {}

if (rows.length === 0) {
  try {
    const all = $('Normalize All Staff').first().json;
    if (all && all.staff_rows) rows = all.staff_rows;
  } catch (e) {}
}

return [{
  json: {
    staff_ids: rows.map((r) => r.id),
    staff_count: rows.length,
    staff_ids_in: 'in.(' + rows.map((r) => r.id).join(',') + ')',
  },
}];

// get_availability — Compute Staff Slots
// Unions every matched staff member's weekly window for the target day,
// minus existing (non-cancelled) appointments in that window. Slot
// spacing mirrors the calendar branch: each offered option starts at
// least one service-length after the last, so three options are three
// genuinely different times, not 10:00/10:15/10:30.
const SLOT_STEP_MINUTES = 15;
const MIN_SLOTS = 1;
const MAX_SLOTS = 3;

const dateInfo = $('Resolve Date').first().json;
const serviceMatch = $('Normalize Service Match').first().json;
const tz = dateInfo.business_timezone;
const duration = Number(serviceMatch.duration_minutes) || 30;
const targetDay = DateTime.fromISO(dateInfo.day_start_iso, { zone: tz });
const now = DateTime.fromISO(dateInfo.search_from_iso, { zone: tz });

let availabilityRows = [];
try { availabilityRows = $('Normalize Staff Availability').first().json.availability_rows || []; } catch (e) {}

let appointmentRows = [];
try { appointmentRows = $('Normalize Staff Appointments').first().json.appointment_rows || []; } catch (e) {}

const busy = appointmentRows
  .map((a) => ({
    start: DateTime.fromISO(a.start_time, { zone: tz }).toMillis(),
    end: DateTime.fromISO(a.end_time, { zone: tz }).toMillis(),
  }))
  .filter((b) => b.end > b.start);

function overlapsBusy(startMs, endMs) {
  return busy.some((b) => startMs < b.end && endMs > b.start);
}

const candidates = [];
for (const window of availabilityRows) {
  const startParts = String(window.start_time).slice(0, 5).split(':').map(Number);
  const endParts = String(window.end_time).slice(0, 5).split(':').map(Number);
  const windowStart = targetDay.set({ hour: startParts[0], minute: startParts[1], second: 0, millisecond: 0 });
  const windowEnd = targetDay.set({ hour: endParts[0], minute: endParts[1], second: 0, millisecond: 0 });

  let cursor = windowStart;
  if (targetDay.hasSame(now, 'day') && cursor < now) {
    const stepMs = SLOT_STEP_MINUTES * 60 * 1000;
    cursor = DateTime.fromMillis(Math.ceil(now.toMillis() / stepMs) * stepMs, { zone: tz });
  }

  while (cursor.plus({ minutes: duration }) <= windowEnd) {
    const slotEnd = cursor.plus({ minutes: duration });
    if (!overlapsBusy(cursor.toMillis(), slotEnd.toMillis())) {
      candidates.push({ start: cursor, end: slotEnd });
    }
    cursor = cursor.plus({ minutes: SLOT_STEP_MINUTES });
  }
}

candidates.sort((a, b) => a.start.toMillis() - b.start.toMillis());

const chosen = [];
for (const candidate of candidates) {
  if (chosen.length === 0) {
    chosen.push(candidate);
  } else {
    const last = chosen[chosen.length - 1];
    if (candidate.start >= last.start.plus({ minutes: duration })) {
      chosen.push(candidate);
    }
  }
  if (chosen.length >= MAX_SLOTS) break;
}

const slots = chosen.map((c) => ({
  start: c.start.toISO(),
  end: c.end.toISO(),
  label: c.start.toFormat("cccc, LLLL d 'at' h:mm a"),
}));

const businessIdInput = $('Validate Format').first().json.business_id_input;

return [{
  json: {
    enough_slots: slots.length >= MIN_SLOTS,
    response_ok: {
      business_id: businessIdInput,
      source: 'staff_roster',
      service_or_staff: $('Validate Format').first().json.service_or_staff,
      duration_minutes: duration,
      timezone: tz,
      slot_count: slots.length,
      slots,
    },
    response_error: {
      error: 'no_slots_available',
      business_id: businessIdInput,
      source: 'staff_roster',
      message: 'No open slots found for that day. Offer create_callback_request instead.',
      slot_count: 0,
      slots: [],
    },
  },
}];

const SEARCH_DAYS = 14;
const input = $('Resolve Date').first().json;
const start = DateTime.fromISO(input.search_from_iso, { zone: input.business_timezone });
const end = start.plus({ days: SEARCH_DAYS }).endOf('day');

return [{ json: { search_days: SEARCH_DAYS, time_min: start.toUTC().toISO(), time_max: end.toUTC().toISO() } }];

function resolveHours(openingHours, weekdayNum) {
  const DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const dayName = DAY_NAMES[weekdayNum - 1];
  const schedule = openingHours && Array.isArray(openingHours.schedule) ? openingHours.schedule : null;
  if (!schedule || schedule.length === 0) {
    // Not configured -- fall back rather than guess a business's real hours.
    if (weekdayNum === 7) return { closed: true };
    return { closed: false, open: '09:00', close: '19:00' };
  }
  const row = schedule.find((d) => d && d.day === dayName);
  if (!row) return { closed: true };
  return row.closed ? { closed: true } : { closed: false, open: row.open, close: row.close };
}

// get_availability — Compute Available Slots (google_calendar branch)
const SLOT_STEP_MINUTES = 15;
const MIN_SLOTS = 2;
const MAX_SLOTS = 3;
const MAX_CANDIDATES = 500;

const dateInfo = $('Resolve Date').first().json;
const settings = $('Normalize Settings').first().json;
const serviceMatch = $('Normalize Service Match').first().json;
const searchDays = $('Compute Search Window').first().json.search_days;

const tz = dateInfo.business_timezone;
const duration = Number(serviceMatch.duration_minutes) || 30;
const searchFrom = DateTime.fromISO(dateInfo.search_from_iso, { zone: tz });
const openingHours = settings.opening_hours;

const busy = $input
  .all()
  .map((item) => item.json)
  .filter((e) => e && e.id && e.status !== 'cancelled' && e.transparency !== 'transparent')
  .map((e) => {
    const rawStart = e.start && (e.start.dateTime || e.start.date);
    const rawEnd = e.end && (e.end.dateTime || e.end.date);
    if (!rawStart || !rawEnd) return null;
    return {
      start: DateTime.fromISO(rawStart, { zone: tz }).toMillis(),
      end: DateTime.fromISO(rawEnd, { zone: tz }).toMillis(),
    };
  })
  .filter((b) => b && b.end > b.start);

function overlapsBusy(startMs, endMs) {
  return busy.some((b) => startMs < b.end && endMs > b.start);
}

function ceilToStep(dt) {
  const stepMs = SLOT_STEP_MINUTES * 60 * 1000;
  return DateTime.fromMillis(Math.ceil(dt.toMillis() / stepMs) * stepMs, { zone: tz });
}

const candidates = [];

for (let dayOffset = 0; dayOffset <= searchDays; dayOffset++) {
  const day = searchFrom.plus({ days: dayOffset }).startOf('day');
  const hours = resolveHours(openingHours, day.weekday);
  if (hours.closed) continue;

  const [openH, openM] = hours.open.split(':').map(Number);
  const [closeH, closeM] = hours.close.split(':').map(Number);
  const open = day.set({ hour: openH, minute: openM, second: 0, millisecond: 0 });
  const close = day.set({ hour: closeH, minute: closeM, second: 0, millisecond: 0 });

  let cursor = dayOffset === 0 ? ceilToStep(searchFrom) : open;
  if (cursor < open) cursor = open;

  while (cursor.plus({ minutes: duration }) <= close) {
    const slotEnd = cursor.plus({ minutes: duration });
    if (!overlapsBusy(cursor.toMillis(), slotEnd.toMillis())) {
      candidates.push({ start: cursor, end: slotEnd });
    }
    cursor = cursor.plus({ minutes: SLOT_STEP_MINUTES });
  }

  if (candidates.length >= MAX_CANDIDATES) break;
}

const chosen = [];
for (const candidate of candidates) {
  if (chosen.length === 0) {
    chosen.push(candidate);
  } else {
    const last = chosen[chosen.length - 1];
    if (candidate.start >= last.start.plus({ minutes: duration })) {
      chosen.push(candidate);
    }
  }
  if (chosen.length >= MAX_SLOTS) break;
}

const slots = chosen.map((c) => ({
  start: c.start.toISO(),
  end: c.end.toISO(),
  label: c.start.toFormat("cccc, LLLL d 'at' h:mm a"),
}));

const enough = slots.length >= MIN_SLOTS;
const searchedThrough = searchFrom.plus({ days: searchDays }).endOf('day');
const businessIdInput = $('Validate Format').first().json.business_id_input;

return [{
  json: {
    enough_slots: enough,
    response_ok: {
      business_id: businessIdInput,
      source: 'google_calendar',
      service_or_staff: $('Validate Format').first().json.service_or_staff,
      duration_minutes: duration,
      timezone: tz,
      slot_count: slots.length,
      slots,
    },
    response_error: {
      error: 'no_slots_available',
      business_id: businessIdInput,
      source: 'google_calendar',
      message: 'No open slots in the next ' + searchDays + ' days. Offer create_callback_request instead.',
      slot_count: 0,
      slots: [],
    },
  },
}];
